// Six rows shaped like a real sheet, including the problems the checks catch.
const rows = [
  { row_number: 2, id: 'C-1001', name: 'ada lovelace', email: 'Ada@Example.com ', status: 'Active', amount: '1,250.00' },
  { row_number: 3, id: 'C-1002', name: 'Grace Hopper', email: 'grace@example.com', status: 'paused', amount: '300' },
  { row_number: 4, id: 'C-1003', name: 'Alan Turing', email: 'alan@example', status: 'active', amount: '90' },
  { row_number: 5, id: 'C-1002', name: 'Grace H. (copy)', email: 'grace2@example.com', status: 'active', amount: '10' },
  { row_number: 6, id: '', name: 'No id row', email: 'noid@example.com', status: 'active', amount: '5' },
  { row_number: 7, id: 'C-1004', name: 'Katherine Johnson', email: 'katherine@example.com', status: 'retired', amount: 'n/a' },
];
return rows.map(r => ({ json: r }));

// One rule per line. Rows that fail go to the rejects report instead of the database.
// Change the column names on the right to match your sheet's headers.
const cfg = $('Config').first().json;
const allowed = String(cfg.allowed_statuses).split(',').map(s => s.trim().toLowerCase());
const fnv = s => { let h = 0x811c9dc5; for (const c of s) { h ^= c.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16); };
const seen = new Set();
const valid = [], rejects = [];
for (const i of $input.all()) {
  const r = i.json;
  const row = {
    external_id: String(r.id ?? r.ID ?? '').trim(),
    name: String(r.name ?? r.Name ?? '').trim().replace(/\s+/g, ' ').replace(/\b\w/g, c => c.toUpperCase()),
    email: String(r.email ?? r.Email ?? '').trim().toLowerCase(),
    status: String(r.status ?? r.Status ?? 'active').trim().toLowerCase(),
    amount: null,
  };
  // "1,250.00" and "300" load as numbers; "n/a" is rejected.
  const rawAmount = String(r.amount ?? r.Amount ?? '').trim();
  if (rawAmount) { const n = rawAmount.replace(/[^0-9.-]/g, ''); row.amount = /\d/.test(n) ? Number(n) : NaN; }
  const errors = [];
  if (!row.external_id) errors.push('missing id');
  else if (seen.has(row.external_id)) errors.push(`duplicate id ${row.external_id}`);
  if (row.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(row.email)) errors.push(`bad email "${row.email}"`);
  if (!allowed.includes(row.status)) errors.push(`unknown status "${row.status}"`);
  if (row.amount !== null && Number.isNaN(row.amount)) errors.push(`amount "${rawAmount}" is not a number`);
  if (row.external_id) seen.add(row.external_id);
  if (errors.length) { rejects.push({ sheet_row: r.row_number ?? null, id: row.external_id, errors: errors.join('; ') }); continue; }
  row.row_hash = fnv(JSON.stringify([row.name, row.email, row.status, row.amount]));
  valid.push(row);
}
return [{ json: { valid, rejects, sheet_rows: $input.all().length } }];

