// Compare the sheet with the table: new, changed, unchanged, gone.
const cfg = $('Config').first().json;
const { valid, rejects, sheet_rows } = $('Validate and clean').first().json;
const rows = $input.first().json.rows;
const current = new Map((typeof rows === 'string' ? JSON.parse(rows) : rows).map(r => [r.external_id, r]));
const upserts = [], counts = { sheet_rows, new: 0, changed: 0, restored: 0, unchanged: 0, rejected: rejects.length };
for (const row of valid) {
  const db = current.get(row.external_id);
  if (!db) { counts.new++; upserts.push(row); }
  else if (db.deleted) { counts.restored++; upserts.push(row); }
  else if (db.row_hash !== row.row_hash) { counts.changed++; upserts.push(row); }
  else counts.unchanged++;
}
// A rejected row still exists in the sheet, so it is never treated as deleted.
const inSheet = new Set([...valid.map(r => r.external_id), ...rejects.map(r => r.id).filter(Boolean)]);
const gone = [...current.values()].filter(r => !r.deleted && !inSheet.has(r.external_id)).map(r => r.external_id);
const live = [...current.values()].filter(r => !r.deleted).length;
// Safety cap: a cleared or renamed tab would otherwise mark the whole table deleted.
const deleteBlocked = gone.length > 0 && live > 0 && gone.length / live > Number(cfg.max_delete_share);
const deletes = cfg.soft_delete_missing && !deleteBlocked ? gone : [];
counts.deleted = deletes.length;
return [{ json: { upserts, deletes, rejects, counts, gone: gone.length, delete_blocked: deleteBlocked } }];

// One item per new or changed row, with the time it was loaded.
const now = new Date().toISOString();
return $input.first().json.upserts.map(r => ({ json: { ...r, updated_at: now, deleted_at: null } }));

