// One message: what changed, which rows were not loaded and why.
const cfg = $('Config').first().json;
const { counts, rejects, gone, delete_blocked } = $json;
const lines = [
  `${cfg.workflow_label}: ${counts.sheet_rows} sheet rows. ${counts.new} new, ${counts.changed} changed, ${counts.restored} restored, ${counts.unchanged} unchanged, ${counts.deleted} marked deleted, ${counts.rejected} not loaded.`,
];
if (delete_blocked) lines.push(`${gone} table rows are missing from the sheet, more than ${Math.round(cfg.max_delete_share * 100)}% of the table, so none were marked deleted. Check the tab, then raise max_delete_share if it is intended.`);
if (rejects.length) lines.push('Not loaded:', ...rejects.slice(0, 30).map(r => `- row ${r.sheet_row}: ${r.errors}`));
if (rejects.length > 30) lines.push(`...and ${rejects.length - 30} more.`);
return [{ json: { text: lines.join('\n') } }];

// One alert for every failure path. $prevNode names the step that failed.
const cfg = $('Config').first().json;
return $input.all().slice(0, 1).map(i => {
  const e = i.json.error;
  const msg = String((typeof e === 'string' ? e : e && (e.description || e.message)) || i.json.message || 'Open the execution in n8n for the reason (often a missing credential).').slice(0, 400);
  return { json: { text: `${cfg.workflow_label}: ${$prevNode.name} failed. Nothing after it ran. ${msg}` } };
});

