```sql
create table records (external_id text primary key, name text, email text, status text, amount numeric(12,2), row_hash text, updated_at timestamptz, deleted_at timestamptz);
create table sync_runs (id bigserial primary key, run_at timestamptz default now(), sheet_rows int, new_rows int, changed_rows int, restored_rows int, unchanged_rows int, rejected_rows int, deleted_rows int, delete_blocked boolean);
